  CREATE PROCEDURE [bud].[jsSearchBudgetsByCompany]      @company INT = 1,  -- Pass company ID: 1=OIL, 2=BEVERAGE, 3=MART      @docEntry INT = NULL,      @cardName VARCHAR(100) = "BSES RAJDHANI POWER LIMITED ELECTRICITY DELHI VEND",      @month VARCHAR(MAX) = NULL,      @status VARCHAR(10) = NULL  -- 'A' for Approved, 'R' for Rejected, 'P' for Pending, NULL for All  AS  BEGIN      SET NOCOUNT ON;            -- Validate input: At least one search parameter must be provided      IF @docEntry IS NULL AND @cardName IS NULL      BEGIN          RAISERROR('At least one search parameter (docEntry or cardCode) must be provided', 16, 1);          RETURN;      END            -- Map company ID to company name      DECLARE @companyName VARCHAR(100);            SET @companyName = CASE @company          WHEN 1 THEN 'OIL'          WHEN 2 THEN 'BEVERAGE'          WHEN 3 THEN 'MART'          ELSE NULL      END;            -- Validate company ID      IF @companyName IS NULL      BEGIN          RAISERROR('Invalid company ID. Valid values are: 1 (OIL), 2 (BEVERAGE), 3 (MART)', 16, 1);          RETURN;      END            -- Get all budgets filtered by docEntry and/or cardName for all status types      SELECT DISTINCT           wf.docId AS BudgetId,          d.objType,          d.company AS company,          @company AS companyId,          bt.DocEntry,          bt.ObjectName,          bt.CardCode,          bt.CardName,          bt.DocDate,          SUM(bt.AMOUNT) AS TotalAmount,          --wf.status AS ApprovalStatus,          --CASE wf.status          --    WHEN 'A' THEN 'Approved'          --    WHEN 'R' THEN 'Rejected'          --    WHEN 'P' THEN 'Pending'          --    ELSE 'Unknown'          --END AS StatusDescription,          --wf.userId AS ApprovedBy,          --wf.stageId,          --wf.createdOn AS ApprovalDate,          --wf.description,          bt.CURRENTMONTH,          bt.Budget_Owner as BudgetOwner,          bt.OwnerCode,          bt.[Approver Name] as ApproverName,          bt.ApprovalCode      FROM bud.jsBudgetStatusWorkflow wf      INNER JOIN bud.jsDocEnrtyDetail d ON wf.docId = d.docId      INNER JOIN bud.jsDocEntry de ON de.id = wf.docId      INNER JOIN bud.jsBudgetTable bt           ON bt.docEntry = de.docEntry           AND bt.ObjType = d.objType           AND bt.Branch = d.company          AND bt.LineNum = d.lineNum           AND bt.VisOrder = d.visOrder      WHERE d.company = @companyName  -- Use mapped company name        AND (@status IS NULL OR wf.status = @status)        AND (@docEntry IS NULL OR bt.DocEntry = @docEntry)        AND (@cardName IS NULL OR bt.CardName = @cardName)        AND (@month IS NULL OR bt.CURRENTMONTH = @month)      GROUP BY           wf.docId, d.objType, d.company, bt.DocEntry, bt.ObjectName,           bt.CardCode, bt.CardName, bt.DocDate,          wf.status, wf.userId, wf.stageId, wf.createdOn, wf.description, bt.CURRENTMONTH,          bt.Budget_Owner, bt.OwnerCode, bt.[Approver Name], bt.ApprovalCode      ORDER BY           --wf.status,          bt.DocEntry,           bt.CURRENTMONTH;  END;
